    reader = csv.DictReader(f)
    for row in reader:
        disp_map[row['account_id']] = row['client_id']

# Read trans.csv and filter for cash withdrawals by client 3356
results = []
with open('csv/trans.csv', 'r') as f:
    reader = csv.DictReader(f)
