        if client_id == '3356':
            operation = row['operation']
            if operation.startswith('VYBER'):
                results.append({
                    'trans_id': row['trans_id'],
                    'date': row['date'],
                    'operation': operation,
                    'amount': row['amount'],
                    'balance': row['balance']
                })

print(f'Found {len(results)} cash withdrawals for client 3356')
for r in results[:10]:
    print(r)
if len(results) > 10:
    print('... and more')

